// BRO-5359: every hook registered in .claude/settings.json must be wired into home-rooted cloud sessions.
// Those sessions (every multi-repo / create_session run) load /home/user/.claude/settings.json, generated by
// scripts/install-home-claude-config.js, and NOT the repo settings. The installer only matches
// `.claude/hooks/<name>.sh` (no subdirectory), so a hook registered as `.claude/hooks/lib/x.sh` was silently
// dropped: the review-coverage Stop hook passed every unit test and never ran in a live session.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const { buildSettings } = require('../../scripts/install-home-claude-config.js');
const repoSettings = JSON.parse(fs.readFileSync(path.join(ROOT, '.claude', 'settings.json'), 'utf8'));

const commands = Object.entries(repoSettings.hooks).flatMap(([event, groups]) =>
  groups.flatMap((g) => g.hooks.filter((h) => h.type === 'command').map((h) => ({ event, command: h.command }))));

test('every hook command in .claude/settings.json names a top-level .claude/hooks/<name>.sh', () => {
  for (const { event, command } of commands) {
    const m = /\.claude\/hooks\/([^\s'"]+\.sh)/.exec(command);
    assert.ok(m, `${event}: no hook script found in: ${command.slice(0, 100)}`);
    assert.ok(!m[1].includes('/'), `${event}: ${m[1]} is in a subdirectory; the home installer wires only .claude/hooks/<name>.sh, so it would never run in home-rooted cloud sessions`);
  }
});

test('the home installer wires every registered hook, one for one', () => {
  const { wired } = buildSettings(repoSettings, '/home/user');
  assert.equal(wired.length, commands.length, `repo registers ${commands.length} hook commands, installer wired ${wired.length}`);
  assert.ok(wired.includes('Stop:verify-edits.sh'), 'the Stop hook that carries the review-coverage gate is wired');
  assert.ok(wired.includes('PreToolUse:pre-push-land-preflight.sh'), 'the land gate hook is wired');
});
